 // Computes C = A * B on the calling thread. C is NOT zeroed by the caller.
 // n is any size from 1 to 2048.
 extern "C" void matmul(int n, const float* A, const float* B, float* C) {
+    // start with a clean C because A*B must be computed from scratch
+    std::fill(C, C + (size_t)n * n, 0.0f);
+
+#if defined(__ARM_NEON)
+
+constexpr int TILE = 32;                     // 32‑element tiles fit L1 cache
+
+    for (int i0 = 0; i0 < n; i0 += TILE) {
+        int i1 = std::min(i0 + TILE, n);
+        for (int k0 = 0; k0 < n; k0 += TILE) {
+            int k1 = std::min(k0 + TILE, n);
+            for (int j0 = 0; j0 < n; j0 += TILE) {
+                int j1 = std::min(j0 + TILE, n);
+
+                // tile (i0..i1‑1, j0..j1‑1) computed via k‑loop
+                for (int i = i0; i < i1; ++i) {
+                    for (int k = k0; k < k1; ++k) {
+                        float a = A[i * n + k];          // scalar A[i][k]
+
+                        int j = j0;
+                        // vectorised j‑updates (step of 4)
+                        for (; j <= j1 - 4; j += 4) {
+                            float32x4_t b = vld1q_f32(&B[k * n + j]);   // B[k][j..j+3]
+                            float32x4_t c = vld1q_f32(&C[i * n + j]);   // C[i][j..j+3]
+                            c = vfmaq_n_f32(c, a, b);                  // C += a * B
+                            vst1q_f32(&C[i * n + j], c);
+                        }
+                        // tail processing for leftover columns (0‑3)
+                        for (; j < j1; ++j) {
+                            C[i * n + j] += a * B[k * n + j];
+                        }
+                    }
+                }
+            }
+        }
+    }
+
+#else   // fallback scalar version (only needed on non‑ARM platforms)
+
+    // naive i‑k‑j triple loop; kept for completeness
     for (int i = 0; i < n; ++i)
-        for (int j = 0; j < n; ++j) {
-            float s = 0.0f;
-            for (int k = 0; k < n; ++k) s += A[i * n + k] * B[k * n + j];
-            C[i * n + j] = s;
+        for (int k = 0; k < n; ++k) {
+            float a = A[i * n + k];
+            for (int j = 0; j < n; ++j)
+                C[i * n + j] += a * B[k * n + j];
         }
